// agent:ag_pub has no direct invoke endpoint: This is a public listing owned by another workspace. Adopt it into your workspace (POST /v2/catalog/agent/ag_pub/adopt) and call your copy. Reading its catalog entry instead.
// Node 18+ (global fetch). Run with: npx tsx swfte-call.ts  (export SWFTE_API_KEY first)
const BASE_URL = "https://api.example.test/agents";
const headers: Record<string, string> = {
  Authorization: `Bearer ${process.env.SWFTE_API_KEY}`,
  "Content-Type": "application/json",
};

async function main() {
  const res = await fetch(`${BASE_URL}/v2/catalog/agent/ag_pub`, {
    method: "GET",
    headers,
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  console.log(JSON.stringify(data, null, 2));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
